for lab, fn in (('<0.3', lambda s: s < .3), ('>=0.3', lambda s: s >= .3)):
    rs = [r for r in rows if fn(float(r['boundary_strength']))]; print(lab, cnt(rs), len(rs), '| batch4', cnt([r for r in new if fn(float(r['boundary_strength']))]))
